@pragma('vm:entry-point')
int roundCentsByPopcountParity(int cents, int unit) {
  int pop = 0, n = cents;
  while (n != 0) {
    pop += n & 1;
    n >>= 1;
  }
  int remainder = cents & (unit - 1);
  if (remainder == 0) return cents;
  return pop.isOdd ? cents + unit - remainder : cents - remainder;
}

