  final candidate = evaluateInventoryClusterScore;

  expect(candidate([], 2), 0);
  expect(candidate(['axe'], 1), 4);
  expect(candidate(['axe'], 2), -1);
  expect(candidate(['axe', 'axe', 'amulet', 'amulet'], 2), 3);
