List<int> spellCheckDeletionIndices(String word) {
  List<int> result = [];
  int run = 0;
  for (int i = 0; i < word.length; i++) {
    if (i == 0 || word[i] != word[i - 1]) {
      run = 1;
    } else {
      run++;
      if (run > 2) {
