int enclosedSeatGapArea(List<int> reservedSeats, int seatsPerRow) {
  if (reservedSeats.isEmpty) return 0;
  int minRow = 1 << 30, maxRow = -1, minCol = 1 << 30, maxCol = -1;
  for (final seat in reservedSeats) {
