import 'dart:math';

int asciiStrokeBoundingArea(List<String> rows) {
  int minX = 1 << 30, maxX = -1, minY = rows.length, maxY = -1;
  for (int y = 0; y < rows.length; y++) {
    int a = rows[y].indexOf('#');
    if (a >= 0) {
