List<double> shelfCodeCarryover(List<int> codes) {
  if (codes.isEmpty) return [];
  List<double> dp = List.filled(codes.length, 0.0);
  dp[0] = codes[0].isEven ? 1.0 : -1.0;
  for (int i = 1; i < codes.length; i++) {
