bool hasBalancedRetryTokens(String line) {
  var parts = line.split('|');
  if (parts.length != 2 || parts[0].isEmpty) return false;
  var entries = parts[1].split(',');
  int balance = 0;
  for (var e in entries) {
    if (e.length < 2 || (e[0] != '+' && e[0] != '-')) return false;
