int longestCarryoverWifiSpan(List<int> bins, int minimumSignal) {
  int best = 0;
  int span = 0;
  for (final signal in bins) {
    if (signal >= minimumSignal) {
      span++;
    } else if (signal == minimumSignal - 1 && span > 0) {
      span++;
    } else {
      span = 0;
    }
    if (span > best) best = span;
  }
  return best;
}

