int decipherMoistureRunlengthSum(String data) {
  int total = 0;
  for (int i = 0; i < data.length; i += 2) {
    int code = data.codeUnitAt(i);
    int value;
    if (code == 69) {
      value = 1;
    } else if (code == 78) {
      value = 2;
    } else if (code == 88) {
      value = 3;
    } else {
      throw ArgumentError('Invalid shifted category');
    }
    int count = int.parse(data[i + 1]);
    total += value * count;
  }
  return total;
}

