  assert(rankBracketGroupSeedings([], 'GroupA') == 'GroupA: (empty)');
  assert(rankBracketGroupSeedings(['Alpha:3:0:15', 'Beta:3:0:10', 'Gamma:2:1:5'], 'GroupA') == 'GroupA: 1.Alpha 2.Beta 3.Gamma');
