List<List<int>> segmentFloorRequestsByProximity(List<int> floors) {
  if (floors.isEmpty) return [];
  List<List<int>> result = [];
  List<int> current = [floors[0]];
  for (int i = 1; i < floors.length; i++) {
    if ((floors[i] - floors[i - 1]).abs() > 3) {
