bool hasComplementarySensorParity(int packet) {
  int left = packet & 0xFFFF;
  int right = (packet >> 16) & 0xFFFF;
  int popcount(int x) {
    int count = 0;
    while (x != 0) {
      x &= x - 1;
      count++;
    }
    return count;
  }
  return (popcount(left) & 1) != (popcount(right) & 1);
}

