List<num> mostFrequentFloors(List<int> requests) {
  var freq = <int, int>{};
  var top = <int>[];
  int max = 0;
  for (var f in requests) {
    int c = (freq[f] ?? 0) + 1;
    freq[f] = c;
    if (c > max) {
      max = c;
      top = [f];
    } else if (c == max) {
      top.add(f);
    }
  }
  top.sort();
  return top;
}

