@pragma('vm:entry-point')
int evaluateWifiSignalRPN(List<String> tokens) {
  List<int> stack = [];
  for (var t in tokens) {
    if (t == 'A') {
      int b = stack.removeLast();
      int a = stack.removeLast();
      stack.add((a + b) ~/ 2);
    } else if (t == 'X') {
      int b = stack.removeLast();
      int a = stack.removeLast();
      stack.add(a > b ? a : b);
    } else if (t == 'N') {
      int b = stack.removeLast();
      int a = stack.removeLast();
      stack.add(a < b ? a : b);
    } else {
      stack.add(int.parse(t));
    }
  }
  return stack.isEmpty ? 0 : stack.last;
}

