    if (ch == '.') {
      dots++;
      span += 1;
    } else if (ch == '-') {
      dashes++;
      span += 3;
    }
    if (i < morseSymbols.length - 1) {
      span += 1;
    }
  }
  int endDay = span == 0 ? startDay - 1 : startDay + span - 1;
  return 'span:$span,end:$endDay,dots:$dots,dashes:$dashes';
}

