int countCrowdedWifiBins(List<int> readings) {
  final counts = <int, int>{};
  int crowded = 0;
  for (final r in readings) {
    final bin = (-r) ~/ 10;
    counts[bin] = (counts[bin] ?? 0) + 1;
    if (counts[bin] == 3) crowded++;
  }
