void main() {
  assert(parseWifiBinCounts('').toString() == '[0, 0, 0, 0]');
  assert(parseWifiBinCounts('-45 -80 -30 -95 -65').toString() == '[2, 1, 1, 1]');
  assert(parseWifiBinCounts('-50 -51 -68 -69 -80 -81').toString() == '[1, 2, 2, 1]');
  print('All tests passed!');
}

