List<int> findRestockBinIndices(List<int> stockLevels, int threshold, int gap) {
  List<int> result = [];
  int lastPicked = -gap - 1;
  for (int i = 0; i < stockLevels.length; i++) {
    if (stockLevels[i] <= threshold && i - lastPicked >= gap) {
