  assert(countServerLogPairSignals([]) == 0);
  assert(countServerLogPairSignals(['ERROR#a#1', 'ERROR#a#2']) == 2);
  assert(countServerLogPairSignals(['ERROR#a#1', 'WARN#a#1']) == -1);
  print('All tests passed!');
}

