bool isElevatorSequenceFeasible(List<int> requests) {
  if (requests.isEmpty) return true;
  final Set<int> seen = {};
  for (int i = 0; i < requests.length; i++) {
    int floor = requests[i];
    if (seen.contains(floor)) {
      return false;
    }
    seen.add(floor);
    if (i > 0) {
      int diff = (floor - requests[i - 1]).abs();
      if (diff > 5) {
