bool hasBalancedBracketRun(String tape) {
  int total = 0;
  for (int i = 0; i < tape.length; i += 2) {
    if (i + 1 >= tape.length || tape.codeUnitAt(i) < 65 || tape.codeUnitAt(i) > 90) return false;
    int n = tape.codeUnitAt(i + 1) - 48;
