int countStrongEvenRounds(List<List<int>> rounds) {
  int count = 0;
  for (var round in rounds) {
    Map<int, int> freq = {};
    int sum = 0;
    for (var die in round) {
      freq[die] = (freq[die] ?? 0) + 1;
      sum += die;
    }
    int maxFreq = freq.values.fold(0, (a, b) => a > b ? a : b);
    if (maxFreq >= 3 && sum % 2 == 0) {
      count++;
    }
  }
  return count;
}

