int tripleRoundFaceScore(List<int> rounds) {
  final counts = <int, int>{};
  var score = 0;
  for (final face in rounds) {
    final next = (counts[face] ?? 0) + 1;
    counts[face] = next;
    if (next == 3) {
      score += face;
    } else if (next == 4) {
      score -= face;
    }
  }
  return score;
}

