bool hasBalancedTideDirectionChanges(List<int> readings) {
  int rises = 0;
  int falls = 0;
  for (int i = 1; i < readings.length; i++) {
    if (readings[i] == readings[i - 1]) continue;
    if (readings[i] > readings[i - 1]) {
      rises++;
    } else {
