bool hasSafeSensorSpacing(int packed) {
  int reading = packed & 0xFF;
  int rotateBy = (packed >> 8) & 0x7;
  int rotated = ((reading << rotateBy) | (reading >> (8 - rotateBy))) & 0xFF;
  return (rotated & (rotated >> 1)) == 0;
}

