String bestHalfWindowSum(List<int> sizes) {
  int n = sizes.length;
  if (n < 2) return "0:0";
  int k = n ~/ 2, sum = 0, maxSum = 0, maxStart = 0;
  for (int i = 0; i < n; i++) {
    sum += sizes[i];
    if (i >= k) sum -= sizes[i - k];
    if (i == k - 1) {
      maxSum = sum; maxStart = 0;
    } else if (i >= k && sum > maxSum) {
      maxSum = sum; maxStart = i - k + 1;
    }
  }
  return "${maxSum}:${maxStart}";
}

