  final candidate = selectCriticalLogBranch;

  expect(candidate([]), 'empty');
  expect(candidate(['api - ERR']), 'api');
  expect(candidate(['root - OK','a root WARN','b a ERR']), 'root->a->b');
  expect(candidate(['root - OK','x root ERR','y root WARN']), 'root->x');
  expect(candidate(['root - WARN','a root WARN','b a WARN','c b OK']), 'root->a->b->c');
  expect(candidate(['r - OK','a r DROP','b r WARN']), 'r->b');
  expect(candidate(['r - OK','a r DROP']), 'empty');
  expect(candidate(['r - WARN','a r ERR','b r ERR']), 'r->a');
  expect(candidate(['main - OK','a main WARN','b a ERR','c main ERR','d c OK']), 'main->a->b');
  expect(candidate(['x - WARN','bad data line','y x ERR']), 'x->y');
}

