List<int> bucketPacketSizeRotations(List<int> sizes) {
  List<int> out = [0, 0, 0, 0];
  for (int size in sizes) {
    int byte = size & 255;
    int rot = ((byte << 1) & 255) | (byte >> 7);
    int bits = 0;
    int v = rot;
    while (v != 0) {
      bits++;
      v &= v - 1;
    }
    if ((bits & 1) == 0) {
      if ((rot & 24) == 24) {
        out[0]++;
      } else {
        out[1] += rot & 3;
      }
    } else if ((rot & 3) == 0) {
      out[2] += bits;
    } else {
      out[3] += size & 7;
    }
  }
  return out;
}

