  expect(candidate(['#.#','...','#..']), 'speckled');
  expect(candidate(['....','.##.','.##.','....']), 'floating');
  expect(candidate(['##..','##..','..##','..##']), 'anchored');
  expect(candidate(['###','#.#','###']), 'speckled');
  expect(candidate(['###','###','###']), 'floating');
