  final candidate = asciiRowReorderPenalty;

  expect(candidate([], 1), 0);
  expect(candidate(['  '], 1), 0);
  expect(candidate([''], 0), 1);
  expect(candidate(['##'], 3), 1);
  expect(candidate(['##', '/\\'], 1), 0);
  expect(candidate(['/\\', '##'], 1), 2);
  expect(candidate(['aa', '|##'], 1), 3);
  expect(candidate(['/ /', '###', '- -'], 3), 2);
  expect(candidate(['/ /', '###', '- -'], 5), 1);
