int countFrequentOddDominantColors(List<int> pixels) {
  Map<int, int> freq = {};
  for (int p in pixels) {
    int v = p & 0xFFFFFF;
    freq[v] = (freq[v] ?? 0) + 1;
  }
  int count = 0;
  for (int p in freq.keys) {
    if ((freq[p] ?? 0) >= 2) {
      int r = (p >> 16) & 0xFF;
      int g = (p >> 8) & 0xFF;
      int b = p & 0xFF;
      int dominant;
      if (r >= g && r >= b) {
        dominant = r;
      } else if (g >= r && g >= b) {
        dominant = g;
      } else {
        dominant = b;
      }
      if (dominant % 2 != 0) {
        count++;
      }
    }
  }
  return count;
}

