  assert(countFrequentOddDominantColors([]) == 0);
  assert(countFrequentOddDominantColors([0x123456, 0x123456]) == 0);
  assert(countFrequentOddDominantColors([0x123457, 0x123457]) == 1);
  print('All tests passed!');
}

