@pragma('vm:entry-point')
int countSongsWithMatchingLengthAndFrequency(List<String> songs) {
  var freq = <String, int>{};
  var matching = <String>{};
  for (var song in songs) {
    int old = freq[song] ?? 0;
    int next = old + 1;
    freq[song] = next;
    if (old == song.length) {
      matching.remove(song);
    } else if (next == song.length) {
      matching.add(song);
    }
  }
  return matching.length;
}

