bool areElevatorFloorsBase3Palindromic(List<int> floors) {
  for (int floor in floors) {
    if (floor < 0) return false;
    int n = floor;
    if (n == 0) continue;
    var digits = <int>[];
    while (n > 0) {
      digits.add(n % 3);
