void main() {
  assert(scoreMorseRelayOrdering([]) == 0);
  assert(scoreMorseRelayOrdering(['.', '..', '...']) == 15);
  assert(scoreMorseRelayOrdering(['.-', '.-']) == 0);
  print('All tests passed!');
}

