List<int> filterThenScoreDiceRounds(List<List<int>> rounds, int banned) {
  List<int> results = [];
  for (var dice in rounds) {
    int sum = 0;
    int maxDie = -1;
    for (var die in dice) {
      if (die != banned) {
        sum += die;
        if (die > maxDie) maxDie = die;
      }
    }
    int n = dice.length;
    int score;
    if (n == 2 && dice[0] == dice[1]) {
      score = sum * 2;
    } else if (n == 3 && dice[0] == dice[1] && dice[1] == dice[2]) {
      score = sum * 3;
    } else if (n > 3) {
      score = maxDie == -1 ? 0 : maxDie;
    } else {
      score = sum;
    }
    results.add(score);
  }
  return results;
}

