  assert(consolidateAndDiscountInventory([], 0) == 0);
  assert(consolidateAndDiscountInventory([100, 200], 0) == 280);
  assert(consolidateAndDiscountInventory([5, 5, 5], 5) == 12);
  print('All tests passed!');
}

