void main() {
  assert(parseInventoryTapeValue('', 5) == 0);
  assert(parseInventoryTapeValue('+A:2,-B:1', 10) == 4);
  assert(parseInventoryTapeValue('!+A:2', 10) == -3);
  print('All tests passed!');
}

