      if (value < 0) return null;
      sum += value;
      if (j > i) {
        int diff = value - packets[j - 1];
        if (diff.abs() > 5) break;
        if (diff > 0) rising++;
      }
      int len = j - i + 1;
      if (len < 3 || sum % len != 0) continue;
      bool doubledZero = false;
      for (int k = i + 1; k <= j; k++) {
        if (packets[k] == 0 && packets[k - 1] == 0) {
          doubledZero = true;
          break;
        }
      }
      if (!doubledZero && rising * 2 >= len - 1) return '$i-$j';
    }
  }
  return null;
}

