bool isValidTimetableMinutes(List<List<int>> timetable) {
  if (timetable.isEmpty) return true;
  int M = timetable.length;
  int N = timetable[0].length;
  for (int i = 0; i < M; i++) {
    if (timetable[i].length != N) return false;
    for (int j = 0; j < N; j++) {
      int t = timetable[i][j];
      if (t < 0 || t > 1440) return false;
    }
  }
  for (int i = 0; i < M - 1; i++) {
    int minDiff = 1441;
    int maxDiff = 0;
