  expect(candidate([5, -5], 1), 1.0);
  expect(candidate([5, -5], 0), 0.5);
  expect(candidate([4], 4), 0.5);
  expect(candidate([3], 4), -0.25);
  expect(candidate([6], 4), -0.5);
  expect(candidate([2, 2, -2], 2), 1.25);
  expect(candidate([2, 2, 2, -2], 2), 0.25);
  expect(candidate([1, 3], 2), -0.5);
}

